        idempotency_context_availability IN (
            'NOT_EVALUATED',
            'AVAILABLE',
            'MISSING_UPSTREAM_FINALITY_REFERENCE',
            'NEW_UPSTREAM_FINALITY_REFERENCE_REJECTED'
        )
    )
);;


