            'DRY_RUN_ONLY',
            'DISABLED',
            'INVOKED',
            'BLOCKED'
        )
    ),
    CONSTRAINT ck_fiscal_sem_hash_backfill_workflow__guarded_status CHECK (
        guarded_mutation_status IS NULL
        OR guarded_mutation_status IN (
            'NOT_PREPARED',
            'PREPARED_BUT_MUTATION_DISABLED',
            'PREPARED_FOR_CONTROLLED_MUTATION',
            'MUTATED',
            'FAILED',
            'STALE',
            'DISABLED',
            'BLOCKED',
            'UNAVAILABLE'
        )
    )
